{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Zolpidem, an imidazopyridine sharing the query's core heteroaromatic system, has an absolute oral bioavailability of 72 ± 7% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tofacitinib, a nitrile-containing heteroaromatic drug with an amide and basic amine, has an absolute oral bioavailability of approximately 74% in humans, supporting high F for the query's similar polar heteroaromatic/amide architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Basmisanil, a fluorophenyl heteroaromatic amide, has an absolute bioavailability of about 75% in humans, supporting high F for the query's fluorophenyl/heteroaromatic/amide motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "INS018_055, a fluorophenyl/piperazine/amide kinase inhibitor, showed good oral bioavailability in healthy volunteers, supporting high F for the query's piperazine-acyl and fluorophenyl features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Darapladib, a larger lipophilic amide/heteroaromatic, has low absolute bioavailability of 12% in humans; this contradictory low-F evidence is less transferable because the query is more polar with lower logD and a low HBD count.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple human absolute-bioavailability analogues with shared imidazopyridine, heteroaromatic-amide, piperazine, and fluorophenyl features show F ≥ 67-75%, outweighing the one low-F large lipophilic analogue and the uncertain physicochemical prior; therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "All evidence analogues have low Morgan similarity (<0.22), limiting transferability.",
    "The query's high molecular weight, high TPSA, and ionization state create uncertainty about permeability and first-pass metabolism.",
    "No human absolute bioavailability data for a close analogue with the same imidazopyridine-thiazole-cyanide scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

